Example usage: //Encode
charbuf[1024];
char*w=buf;
w=mp_encode_array(w,2);
w=mp_encode_uint(w,10);
w=mp_encode_uint(w,15);

//Decode
constchar*r=buf;
uint32_tsize=mp_decode_array(&r);
for(uint32_ti=0;i<size;i++){
uint64_tval=mp_decode_uint(&r);
}
assert(r==w);
 It is your responsibility to ensure that data has enough space. 

data



- a buffer 



size



- a number of elements 



data + mp_sizeof_array(size)  

mp_sizeof_array

Example usage: charbuf[1024];

//Encode
char*w=buf;
w=mp_encode_map(b,2);
w=mp_encode_str(b,"key1",4);
w=mp_encode_str(b,"value1",6);
w=mp_encode_str(b,"key2",4);
w=mp_encode_str(b,"value2",6);

//Decode
constchar*r=buf;
uint32_tsize=mp_decode_map(&r);
for(uint32_ti=0;i<size;i++){
//Useswitch(mp_typeof(**r))tosupportmoretypes
uint32_tkey_len,val_len;
constchar*key=mp_decode_str(&r,key_len);
constchar*val=mp_decode_str(&r,val_len);
}
assert(r==w);
