 Hint: you can dynamically reallocate the buffer during the process. 

data



- a buffer 



len



- a string length 



data + mp_sizeof_strl(len) 

mp_sizeof_strl()

Usage example: charbuf[1024];

char*w=buf;
//FirstMsgPackobject
w=mp_encode_uint(w,10);

//SecondMsgPackobject
w=mp_encode_array(w,4);
w=mp_encode_array(w,2);
//Beginofaninnerarray
w=mp_encode_str(w,"secondinner1",14);
w=mp_encode_str(w,"secondinner2",14);
//Endofaninnerarray
w=mp_encode_str(w,"second",6);
w=mp_encode_uint(w,20);
w=mp_encode_bool(w,true);

//ThirdMsgPackobject
w=mp_encode_str(w,"third",5);
//EOF

constchar*r=buf;

//FirstMsgPackobject
assert(mp_typeof(**r)==MP_UINT);
mp_next(&r);//skipthefirstobject

//SecondMsgPackobject
assert(mp_typeof(**r)==MP_ARRAY);
mp_decode_array(&r);
assert(mp_typeof(**r)==MP_ARRAY);//innerarray
mp_next(&r);//-->>skiptheentireinnerarray(withallmembers)
assert(mp_typeof(**r)==MP_STR);//second
mp_next(&r);
assert(mp_typeof(**r)==MP_UINT);//20
mp_next(&r);
assert(mp_typeof(**r)==MP_BOOL);//true
mp_next(&r);

//ThirdMsgPackobject
assert(mp_typeof(**r)==MP_STR);//third
mp_next(&r);

assert(r==w);//EOF


data



- the pointer to a buffer 



*data = *data + mp_sizeof_TYPE() where TYPE is mp_typeof(**data)

Usage example: //Encode
charbuf[1024];
char*w=buf;
w=mp_encode_array(w,4);
w=mp_encode_uint(w,10);
w=mp_encode_str(w,"helloworld",strlen("helloworld"));
w=mp_encode_bool(w,true);
w=mp_encode_double(w,3.1415);

//Validate
constchar*b=buf;
intr=mp_check(&b,w);
assert(!r);
assert(b==w);

//Decode
uint32_tsize;
uint64_tival;
constchar*sval;
uint32_tsval_len;
boolbval;
doubledval;

constchar*r=buf;

size=mp_decode_array(&r);
//sizeis4

ival=mp_decode_uint(&r);
//ivalis10;

sval=mp_decode_str(&r,&sval_len);
//svalis"helloworld",sval_lenisstrlen("helloworld")

bval=mp_decode_bool(&r);
//bvalistrue

dval=mp_decode_double(&r);
//dvalis3.1415

assert(r==w);
